#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, m;
    long long values[50][50];
    // 读取原表维度；旋转后行数为m、列数为n。
    scanf("%d%d", &n, &m);
    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < m; ++col) {
            scanf("%lld", &values[row][col]);
        }
    }
    // 按新表行遍历原列，每个新行都从原表底部向上取数。
    for (int row = 0; row < m; ++row) {
        for (int col = 0; col < n; ++col) {
            if (col > 0) {
                printf(" ");
            }
            // 新位置(row,col)对应原位置(n-1-col,row)，数值不变。
            printf("%lld", values[n - 1 - col][row]);
        }
        printf("\n");
    }
    return 0;
}

